const yen=v=>'¥'+Math.round(v??0).toLocaleString('ja-JP');
const date=t=>new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Tokyo',hour12:false});
export function reportRows(e){const r=e.settlement;if(!r)throw Error('请先结算本轮，再导出PNG总结');return [['初始资金',yen(r.initial)],['最终净资金',yen(r.final)],['净收益',yen(r.net)],['收益率',r.returnPct.toFixed(2)+'%'],['胜率',r.winRate==null?'—':r.winRate.toFixed(1)+'%'],['最大回撤',r.maxDrawdown.toFixed(2)+'%'],['建仓 / 平仓次数',r.entries+' / '+r.exits],['盈利 / 亏损合计',yen(r.grossProfit)+' / '+yen(r.grossLoss)],['强平次数',String(r.forced)],['模拟 / 现实用时',r.minutes+' 分 / '+(r.realMinutes??0).toFixed(1)+' 分'],['累计借入',yen(r.loanBorrowed)],['利息 / 未偿债务',yen(r.loanInterest)+' / '+yen(r.unpaidDebt)],['隔夜结算',yen(r.swap)],['借款结果',r.loanDefault?'违约结束':'已清偿'],['评分 / 任务',r.game?r.game.score+'/100 · '+r.game.mission+(r.game.complete?' ✓':''):e.round+' / '+e.seed],['交易模式',r.roundMode==='sprint20'?'现实20分钟 · 免保证金':e.bold?'自由局 · 梭哈挑战':'自由局 · 标准模式']];}
export function reportCanvas(e){const rows=reportRows(e),r=e.settlement,canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1800;const c=canvas.getContext('2d');c.fillStyle='#0b121c';c.fillRect(0,0,1600,1800);const text=(s,x,y,size=24,color='#e7eef7')=>{c.fillStyle=color;c.font=`${size}px "Microsoft YaHei",sans-serif`;c.fillText(s,x,y);};text('久留美模拟器 / 交易复盘',80,100,42,'#64e7b0');text('第 '+e.round+' 局 · '+date(r.finishedAt)+' JST',80,150,24,'#94a6bc');text((r.net>=0?'+':'')+yen(r.net)+'  /  '+r.returnPct.toFixed(2)+'%',80,235,58,r.net>=0?'#64e7b0':'#ff7989');text('最终净资金已扣除未偿借款 · 初始本金 ¥1,000,000',80,280,22,'#94a6bc');
rows.forEach(([label,value],i)=>{const x=80+(i%2)*740,y=345+Math.floor(i/2)*78;text(label,x,y,20,'#94a6bc');text(value,x,y+35,27);});
text('净资金曲线 / 扣除剩余债务',80,1020,28);const points=e.curve;let lo=Math.min(r.initial,r.final,...points.map(p=>p.equity)),hi=Math.max(r.initial,r.final,...points.map(p=>p.equity));const pad=Math.max(100,(hi-lo)*.1);lo-=pad;hi+=pad;const y=v=>1060+(hi-v)/(hi-lo)*280;
for(let i=0;i<4;i++){const yy=1060+i*280/3;c.strokeStyle='#273647';c.beginPath();c.moveTo(80,yy);c.lineTo(1400,yy);c.stroke();text(yen(hi-i*(hi-lo)/3),1410,yy+8,18,'#94a6bc');}c.strokeStyle=r.net>=0?'#64e7b0':'#ff7989';c.lineWidth=3;c.beginPath();points.forEach((p,i)=>{const x=80+i*1320/Math.max(1,points.length-1);i?c.lineTo(x,y(p.equity)):c.moveTo(x,y(p.equity));});c.stroke();text('最近平仓记录',80,1410,28);const logs=e.logs.filter(l=>l.pnl!=null).slice(0,5).reverse();logs.forEach((l,i)=>text(date(l.time)+' · '+l.type+' · '+yen(l.pnl),80,1460+i*42,23,l.pnl>=0?'#64e7b0':'#ff7989'));if(!logs.length)text('本轮没有平仓成交',80,1460,24,'#94a6bc');text('虚构行情与虚拟资金 · V1.0.0 · 胜率按平仓成交（含减仓）统计',80,1735,21,'#94a6bc');if(r.estimated)text('旧存档日志不完整，部分交易统计为估算',80,1770,18,'#ffcb72');return canvas;}
export function exportReport(e){const canvas=reportCanvas(e),a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download=`久留美模拟器-第${e.round}局-${new Date(e.settlement.finishedAt).toISOString().replace(/[:.]/g,'-')}-${e.seed}.png`;a.click();}

